import { Controller } from "@hotwired/stimulus"
import { differenceInDays, secondsToDate } from "helpers/date_helpers"

export default class extends Controller {
  static targets = [ "time", "date", "datetime", "shortdate", "ago", "indays", "daysago", "agoorweekday", "timeordate" ]
  static values = { refreshInterval: Number, locale: String, translations: Object }
  static classes = [ "local-time-value" ]

  #timer

  initialize() {
    const locale = this.localeValue
    const translations = this.translationsValue

    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
    this.dateFormatter = new Intl.DateTimeFormat(locale, { dateStyle: "long" })
    this.shortdateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
    this.datetimeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short", dateStyle: "short" })
    this.agoFormatter = new AgoFormatter(translations)
    this.daysagoFormatter = new DaysAgoFormatter(translations)
    this.datewithweekdayFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
    this.indaysFormatter = new InDaysFormatter(translations)
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(locale, translations)
    this.timeordateFormatter = new TimeOrDateFormatter(locale)
  }

  connect() {
    this.#timer = setInterval(() => this.#refreshRelativeTimes(), 30_000)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  refreshAll() {
    this.constructor.targets.forEach(targetName => {
      this.targets.findAll(targetName).forEach(target => this.#formatTime(this[`${targetName}Formatter`], target))
    })
  }

  refreshTarget(event) {
    const targetName = event.target.dataset.localTimeTarget
    this.#formatTime(this[`${targetName}Formatter`], event.target)
  }

  timeTargetConnected(target) { this.#formatTime(this.timeFormatter, target) }
  dateTargetConnected(target) { this.#formatTime(this.dateFormatter, target) }
  datetimeTargetConnected(target) { this.#formatTime(this.datetimeFormatter, target) }
  shortdateTargetConnected(target) { this.#formatTime(this.shortdateFormatter, target) }
  agoTargetConnected(target) { this.#formatTime(this.agoFormatter, target) }
  indaysTargetConnected(target) { this.#formatTime(this.indaysFormatter, target) }
  daysagoTargetConnected(target) { this.#formatTime(this.daysagoFormatter, target) }
  agoorweekdayTargetConnected(target) { this.#formatTime(this.agoorweekdayFormatter, target) }
  timeordateTargetConnected(target) { this.#formatTime(this.timeordateFormatter, target) }

  #refreshRelativeTimes() {
    this.agoTargets.forEach(target => this.#formatTime(this.agoFormatter, target))
  }

  #formatTime(formatter, target) {
    const date = secondsToDate(parseInt(target.getAttribute("datetime")))
    target.innerHTML = formatter.format(date)
    target.title = this.datetimeFormatter.format(date)
  }
}

class AgoFormatter {
  constructor(translations) { this.translations = translations }

  format(date) {
    const seconds = (new Date() - date) / 1000
    const quantities = [
      [ "year", seconds / 60 / 60 / 24 / 365 ],
      [ "month", seconds / 60 / 60 / 24 / (365 / 12) ],
      [ "week", seconds / 60 / 60 / 24 / 7 ],
      [ "day", seconds / 60 / 60 / 24 ],
      [ "hour", seconds / 60 / 60 ],
      [ "minute", seconds / 60 ]
    ]
    const match = quantities.find(([, quantity]) => quantity >= 1)
    return match ? this.#ago(...match) : this.translations.less_than_minute_ago
  }

  #ago(unit, quantity) {
    const count = Math.floor(quantity)
    const form = count === 1 ? "one" : "other"
    return interpolate(this.translations.ago, { count, unit: this.translations.units[unit][form] })
  }
}

class DaysAgoFormatter {
  constructor(translations) { this.translations = translations }

  format(date) {
    const days = differenceInDays(date, new Date())
    if (days <= 0) return styleableValue(this.translations.today)
    if (days === 1) return styleableValue(this.translations.yesterday)
    return interpolate(this.translations.days_ago, { count: styleableValue(days) })
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale, translations) {
    this.daysAgoFormatter = new DaysAgoFormatter(translations)
    this.weekdayFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
  }

  format(date) {
    return differenceInDays(date, new Date()) <= 1 ? this.daysAgoFormatter.format(date) : this.weekdayFormatter.format(date)
  }
}

class InDaysFormatter {
  constructor(translations) { this.translations = translations }

  format(date) {
    const days = differenceInDays(new Date(), date)
    if (days <= 0) return styleableValue(this.translations.today)
    if (days === 1) return styleableValue(this.translations.tomorrow)
    return interpolate(this.translations.in_days, { count: styleableValue(days) })
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.dateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
  }

  format(date) {
    return differenceInDays(date, new Date()) >= 1 ? this.dateFormatter.format(date) : this.timeFormatter.format(date)
  }
}

function interpolate(template, values) {
  return Object.entries(values).reduce((result, [ key, value ]) => result.replace(`%{${key}}`, value), template)
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
