require "yaml"
def walk(value, path = [])
  case value
  when Hash then value.each { |key, child| walk(child, path + [key]) }
  when Array then value.each_with_index { |child, index| walk(child, path + [index]) }
  else
    text = value.to_s.gsub(/<[^>]+>|https?:\/\/\S+|%\{[^}]+\}/, "").strip
    if text.match?(/[A-Za-z]{3}/) && !text.match?(/[ぁ-んァ-ヶ一-龠]/)
      puts "#{path.join(".")}: #{value.inspect}"
    end
  end
end
